import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        int middle = n / 2;
        long[] inside = new long[3], outside = new long[3];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int v = (int) next();
                boolean onShape = (i <= middle && (j == i || j == n - 1 - i)) || (i >= middle && j == middle);
                (onShape ? inside : outside)[v]++;
            }
        // Try all six ordered pairs (shape value a, background value b), a != b.
        long kept = 0;
        for (int a = 0; a < 3; a++)
            for (int b = 0; b < 3; b++)
                if (a != b) kept = Math.max(kept, inside[a] + outside[b]);
        System.out.println((long) n * n - kept);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	middle := n / 2
	var inside, outside [3]int
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			v := next()
			if (i <= middle && (j == i || j == n-1-i)) || (i >= middle && j == middle) {
				inside[v]++
			} else {
				outside[v]++
			}
		}
	}
	// Try all six ordered pairs (shape value a, background value b), a != b.
	kept := 0
	for a := 0; a < 3; a++ {
		for b := 0; b < 3; b++ {
			if a != b {
				kept = max(kept, inside[a]+outside[b])
			}
		}
	}
	fmt.Println(n*n - kept)
}
